27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (+ and 8 to 15 digits)")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date", columnDefinition = "DATE")
55	    private LocalDate registrationDate;
56	
57	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
58	    private Set<Pet> pets;
59	
60	    public String getAddress() {
61	        return this.address;
62	    }
63	
64	    public void setAddress(String address) {
65	        this.address = address;
66	    }
67	
68	    public String getCity() {
69	        return this.city;
70	    }
71	
72	    public void setCity(String city) {
73	        this.city = city;
74	    }
75	
76	    public String getTelephone() {
77	        return this.telephone;
78	    }
79	
80	    public void setTelephone(String telephone) {
81	        this.telephone = telephone;
82	    }
83	
84	    public String getEmail() {
85	        return this.email;
86	    }
87	
88	    /**
89	     * Stores the email in its canonical lower-cased form so it is always persisted and
90	     * returned lower-cased, regardless of the casing supplied by the client.
91	     */
92	    public void setEmail(String email) {
93	        this.email = email == null ? null : email.toLowerCase(Locale.ROOT);
94	    }
95	
96	    public LocalDate getRegistrationDate() {
97	        return this.registrationDate;
98	    }
99	
100	    public void setRegistrationDate(LocalDate registrationDate) {
101	        this.registrationDate = registrationDate;
102	    }
103	
104	    /**
105	     * On first persist, default the registration date to the server's current date
106	     * when the client did not supply one, leaving any supplied date untouched.
107	     */
108	    @PrePersist
109	    private void defaultRegistrationDate() {
110	        if (this.registrationDate == null) {
111	            this.registrationDate = LocalDate.now();
112	        }
113	    }
114	
115	    protected Set<Pet> getPetsInternal() {
116	        if (this.pets == null) {
117	            this.pets = new HashSet<>();
118	        }
