123	        this.pets = pets;
124	    }
125	
126	    public List<Pet> getPets() {
127	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
128	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
129	        return Collections.unmodifiableList(sortedPets);
130	    }
131	
132	    public void setPets(List<Pet> pets) {
