148	        return getPet(name, false);
149	    }
150	
151	    /**
152	     * Return the Pet with the given name, or null if none found for this Owner.
153	     *
154	     * @param name to test
155	     * @return true if pet name is already in use
156	     */
157	    public Pet getPet(String name, boolean ignoreNew) {
158	        name = name.toLowerCase();
159	        for (Pet pet : getPetsInternal()) {
160	            if (!ignoreNew || !pet.isNew()) {
161	                String compName = pet.getName();
162	                compName = compName.toLowerCase();
163	                if (compName.equals(name)) {
164	                    return pet;
165	                }
166	            }
167	        }
168	        return null;
169	    }
