171	    public Pet getPet(Integer petId) {
172	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
173	    }
174	
175	    @Override
176	    public String toString() {
177	        return new ToStringCreator(this)
178	
179	            .append("id", this.getId())
180	            .append("new", this.isNew())
181	            .append("lastName", this.getLastName())
182	            .append("firstName", this.getFirstName())
183	            .append("address", this.address)
184	            .append("city", this.city)
